        rc = database(spec)
    elif kind == "Job:FileWatcher:Create":
        rc = file_watcher(spec)
    elif kind == "Job:Dummy":
        rc = 0
    else:
        die(121, f"CTM5301 desteklenmeyen is tipi: {kind}")
    say(f"== bitis kodu {rc} ==")
    sys.exit(rc)


